```python
import requests
import json
import os

def scrape_data(username, api_key):
    url = f"https://api.twitter.com/1.1/account/verify_credentials.json?oauth_token={api_key}"
    headers = {"Authorization": f"Bearer {api_key}"}
    response = requests.get(url, headers=headers)
    try:
        data = json.loads(response.content)
        return data["user"]["screen_name"], data["user"]["followers_count"]
    except Exception as e:
        print(f"Error: {e}")
        return None, None

def get_data_from_profile(username, api_key):
    url = f"https://api.twitter.com/1.1/search/tweets.json?q={username}"
    headers = {"Authorization": f"Bearer {api_key}"}
    response = requests.get(url, headers=headers)
    try:
        data = json.loads(response.content)
        return data["statuses"]
    except Exception as e:
        print(f"Error: {e}")
        return None

def main():
    username = "twitterusername"
    api_key = "your_api_key"
    screen_name, followers_count = scrape_data(username, api_key)
    if screen_name and followers_count:
        print(f"Screen name: {screen_name}")
        print(f"Followers count: {followers_count}")
    else:
        print("Failed to scrape data")

if __name__ == "__main__":
    main()
```
Note: This snippet should be used responsibly and in accordance with Twitter's terms of service. Additionally, you should never use a web scraper to scrape data from Twitter without permission. The API is designed to be used for personal, non-commercial purposes only.

