		<ul>
			<li><a href="login.php">Login</a></li>
			<li><a href="register.php">Register</a></li>
			<li><a href="logout.php">Logout</a></li>
		</ul>
	</nav>
	<div class="content">
		<!-- Dashboard content goes here -->
	</div>
</body>
</html>
```
